use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        n > 0,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        forall|i: int|
            0 <= i && i < (list.len() as int) ==>
                new_list[i] == list[((n as int + i) % (list.len() as int))],
{
    let len = list.len();
    debug_assert!(len > 0);
    debug_assert!(n > 0 && n < len);

    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);

    // Help the verifier connect slice-extends to the final rotation property.
    assert(new_list.len() == len);

    // Prove the element-wise postcondition by cases on whether i comes from list[n..] or list[..n].
    assert(forall|i: int|
        0 <= i && i < (len as int) ==>
            new_list[i] == list[((n as int + i) % (len as int))] by
    {
        let nn = n as int;
        let ll = len as int;
        if i < ll - nn {
            // new_list[i] comes from list[n + i]
            assert(((nn + i) % ll) == nn + i);
        } else {
            // new_list[i] comes from list[i - (len - n)]
            assert(0 <= i - (ll - nn) && i - (ll - nn) < nn);
            assert(((nn + i) % ll) == nn + i - ll);
        }
    });

    new_list
}

} // verus!